-- notifications blur
hl.layer_rule({
	match = { namespace = "notifications" },
	blur = true,
})

-- rofi animation
hl.layer_rule({
	match = { namespace = "match:namespace rofi" },
	animation = "slide",
})

-- copyq rules float, size, pos
hl.window_rule({
	match = {
		class = "^(com\\.github\\.hluk\\.copyq)$",
	},
	float = true,
	size = "400 500",
	move = "35% 30%",
})
